548	/** Applies one stream event to the pending exchange. */
549	export function applyChatEvent(pending: PendingExchange, event: { type: string; id?: string; name?: string; state?: ToolStep["state"]; input?: unknown; output?: string; answer?: string; text?: string; steps?: string[]; steers?: { id: string; content: string }[] }): PendingExchange {
550	  if (event.type === "delta" && event.text) return { ...pending, answer: (pending.answer ?? "") + event.text, streaming: true };
551	  if (event.type === "tool" && event.name && event.state) {
552	    const step: ToolStep = { id: event.id, name: event.name, state: event.state, ...(event.input !== undefined && { input: event.input }), ...(event.output !== undefined && { output: event.output }) };
553	    const index = pending.tools.findIndex(tool => event.id ? tool.id === event.id : tool.name === event.name && tool.state === "running");
554	    return { ...pending, tools: index < 0 ? [...pending.tools, step] : pending.tools.map((tool, i) => i === index ? { ...tool, ...step } : tool) };
555	  }
556	  if (event.type === "steered" && event.steers?.length) return { ...pending, steers: [...pending.steers ?? [], ...event.steers.map(steer => steer.content)] };
557	  if (event.type === "plan" && event.steps) return { ...pending, plan: event.steps };
558	  if (event.type === "answer" && event.answer) return { ...pending, answer: event.answer, streaming: false };
559	  return pending;
560	}
