631	export type EntityNames = Partial<Record<"account" | "category" | "merchant", Map<string, string>>>;
632	
633	const CURRENCY = /^[A-Z]{3}$/;
634	const INTEGER = /^-?\d{1,19}$/;
635	const ID_KEY = /^(account|category|merchant)(?:_id|Id)?$/;
