637	function money(value: unknown, currency: unknown): string | null {
638	  if (typeof currency !== "string" || !CURRENCY.test(currency)) return null;
639	  if (typeof value === "string" ? !INTEGER.test(value) : !Number.isSafeInteger(value)) return null;
640	  try { return formatMoney(value as string | number, currency); } catch { return null; }
