643	/**
644	 * The tool result as the model reads it: internal evidence is dropped, minor-unit amounts gain a
645	 * formatted sibling (`amount_minor` → `amount_formatted`, `spendingMinor` → `spendingFormatted`) and
646	 * account/category/merchant ids gain their owned names. Exact minor units and currencies are kept.
647	 */
648	export function readableToolOutput(output: unknown, names: EntityNames = {}): unknown {
649	  function walk(value: unknown, inherited?: string): unknown {
650	    if (Array.isArray(value)) return value.map(item => walk(item, inherited));
651	    if (!value || typeof value !== "object") return value;
652	    const row = value as Record<string, unknown>;
653	    const currency = [row.currency_code, row.currencyCode, row.currency, inherited].find(item => typeof item === "string" && CURRENCY.test(item)) as string | undefined;
654	    const result: Record<string, unknown> = {};
655	    for (const [key, child] of Object.entries(row)) {
656	      if (INTERNAL_KEYS.has(key)) continue;
657	      result[key] = walk(child, CURRENCY.test(key) ? key : currency);
658	      const minor = /^(.*?)(_minor|Minor)$/.exec(key);
659	      if (minor) {
660	        // Per-currency maps such as { EUR: "1200" } are formatted per key.
661	        const formatted = child && typeof child === "object" && !Array.isArray(child)
662	          ? Object.fromEntries(Object.entries(child).flatMap(([code, amount]) => { const shown = money(amount, code); return shown ? [[code, shown]] : []; }))
663	          : money(child, currency);
664	        if (formatted && (typeof formatted === "string" || Object.keys(formatted).length)) result[`${minor[1]}${minor[2] === "Minor" ? "Formatted" : "_formatted"}`] = formatted;
665	      } else if ((key === "netWorth" || key === "accountBalanceTotals") && child && typeof child === "object") {
666	        result[`${key}Formatted`] = Object.fromEntries(Object.entries(child).flatMap(([code, amount]) => { const shown = money(amount, code); return shown ? [[code, shown]] : []; }));
667	      }
668	      const id = ID_KEY.exec(key);
669	      if (id && typeof child === "string") {
670	        const name = names[id[1] as keyof EntityNames]?.get(child);
671	        if (name) result[key.includes("_") ? `${id[1]}_name` : `${id[1]}Name`] = name;
672	      }
673	    }
674	    return result;
675	  }
676	  return walk(output);
677	}
